# --- quotas ---------------------------------------------------------

def declare_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or set(raw) != {"workflows", "executions"}:
        raise ValidationError("quota must contain exactly workflows and executions")
    limits = {}
    for field in ("workflows", "executions"):
        value = raw[field]
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"quota {field} must be a positive integer")
        if value <= 0:
            raise ValidationError(f"quota {field} must be a positive integer")
        limits[field] = value

    def apply() -> dict[str, Any]:
        self.store.connection.execute(
            "INSERT INTO quotas(tenant, workflows, executions, updated_at) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(tenant) DO UPDATE SET workflows = excluded.workflows, "
            "executions = excluded.executions, updated_at = excluded.updated_at",
            (tenant, limits["workflows"], limits["executions"], self.store.now()),
        )
        return {"quota": {"workflows": limits["workflows"], "executions": limits["executions"]}}

    with self._operation():
        return self._idempotent(key, "declare-quota", apply, tenant)

def get_quota(self, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            row = self.store.connection.execute(
                "SELECT workflows, executions FROM quotas WHERE tenant = ?",
                (tenant,),
            ).fetchone()
            if row is None:
                return {"quota": None}
            return {"quota": {"workflows": row["workflows"], "executions": row["executions"]}}

def quota_status(self, tenant: str) -> dict[str, Any]:
    """Report each limited resource's declared limit, current holding, and remaining room.

    Read-only: it writes no metering record and changes no declared quota,
    usage, bill, schedule, approval, or replay conclusion. The holding is
    the same real count the quota decision uses (a row count for the
    tenant); the remaining room is limit minus holding, reported truthfully
    as a negative number when a limit was lowered below the current holding
    instead of being clamped to zero. Resources appear workflows first and
    executions second. A tenant that has declared no quota gets the
    definite empty result ``{"status": null}`` — neither resource is listed.
    Another tenant's quota and holdings are never visible.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            limits = self._quota_limits(tenant)
            if limits is None:
                return {"status": None}
            status = {}
            for kind in ("workflows", "executions"):
                ceiling = limits[kind]
                held = self.store.connection.execute(
                    f"SELECT COUNT(*) AS held FROM {kind} WHERE tenant = ?",
                    (tenant,),
                ).fetchone()["held"]
                status[kind] = {"limit": ceiling, "held": held, "remaining": ceiling - held}
            return {"status": status}

def delete_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Remove the tenant's declared quota as a whole.

    The body must be an empty object; deleting the quota of a tenant that
    never declared one is the same definite empty result as deleting one
    it held. After the delete the tenant holds no declared limits, so both
    quota reads report the never-declared empty results and later writes
    run without quota checks. Existing workflows and executions are not
    deleted or made unusable, recorded usage counts and bill conclusions
    are untouched, and the delete itself writes no metering record. The
    route requires a tenant and an idempotency key: repeating the same
    delete with the same key returns the first result without a second
    effect, while the same key on another operation is the usual 409
    conflict and leaves every declaration in place.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    self._empty_body(raw, "delete quota")

    def apply() -> dict[str, Any]:
        # Removing a declaration that was never made deletes no row but
        # is still the same definite empty result, never an error.
        self.store.connection.execute(
            "DELETE FROM quotas WHERE tenant = ?",
            (tenant,),
        )
        return {"quota": None}

    with self._operation():
        return self._idempotent(key, "delete-quota", apply, tenant)

def declare_prices(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Declare the tenant's price table, replacing it as a whole.

    The body is a JSON object whose keys name metered types and whose
    values are positive integer-cent prices. A type the table omits keeps
    the built-in default price. A non-object body, a missing or unknown
    field, or a non-positive, non-integer, boolean, or non-finite price is
    a validation error that writes nothing. The route requires a tenant
    and an idempotency key; repeating the same declaration with the same
    key returns the first result without a second replacement, while the
    same key on another operation is the usual 409 conflict.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or not raw:
        raise ValidationError("prices must be a non-empty object of metered types to positive integer prices")
    prices: dict[str, int] = {}
    for usage_type, value in raw.items():
        if usage_type not in USAGE_TYPES:
            raise ValidationError(f"unknown metered type: {usage_type}")
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"price for {usage_type} must be a positive integer")
        if value <= 0:
            raise ValidationError(f"price for {usage_type} must be a positive integer")
        prices[usage_type] = value
    document = self.store.encode(prices)

    def apply() -> dict[str, Any]:
        # The history record shares the change's effective timestamp and
        # commits in the same transaction, so a reader always sees the
        # table and its history agree.
        occurred_at = self.store.now()
        self.store.connection.execute(
            "INSERT INTO prices(tenant, document, updated_at) VALUES (?, ?, ?) "
            "ON CONFLICT(tenant) DO UPDATE SET document = excluded.document, "
            "updated_at = excluded.updated_at",
            (tenant, document, occurred_at),
        )
        snapshot = dict(sorted(prices.items()))
        self._record_price_history(tenant, PRICE_ACTION_DECLARE, snapshot, occurred_at)
        return {"prices": snapshot}

    with self._operation():
        return self._idempotent(key, "declare-prices", apply, tenant)

def delete_prices(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Remove the tenant's declared price table as a whole.

    The body must be an empty object; deleting a table that was never
    declared is the same definite empty result as deleting one that was.
    After the delete the tenant holds no table of its own, so later bills
    use the built-in defaults; recorded usage and bills already taken are
    untouched. The route requires a tenant and an idempotency key:
    repeating the same delete with the same key returns the first result
    without a second effect, while the same key on another operation is
    the usual 409 conflict and leaves every table in place.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    self._empty_body(raw, "delete prices")

    def apply() -> dict[str, Any]:
        # Removing a table that was never declared deletes no row but is
        # still the same definite empty result, never an error; the delete
        # itself still takes effect, so it leaves its own history record.
        occurred_at = self.store.now()
        self.store.connection.execute(
            "DELETE FROM prices WHERE tenant = ?",
            (tenant,),
        )
        self._record_price_history(tenant, PRICE_ACTION_DELETE, None, occurred_at)
        return {"prices": None}

    with self._operation():
        return self._idempotent(key, "delete-prices", apply, tenant)

